package com.chatserver.realtime

import io.ktor.server.application.*
import io.ktor.server.engine.*
import io.ktor.server.netty.*
import io.ktor.server.response.*
import io.ktor.server.routing.*
import io.ktor.server.websocket.*
import io.ktor.websocket.*
import io.ktor.server.plugins.contentnegotiation.*
import io.ktor.serialization.kotlinx.json.*
import io.ktor.server.sessions.*
import io.ktor.server.html.*
import kotlinx.html.*
import java.util.concurrent.ConcurrentHashMap
import java.util.Collections

data class TenantConfig(
    val tenantId: String,
    val displayName: String,
    val allowedOrigins: List<String>,
    val securityPolicy: SecurityPolicy
)

data class SecurityPolicy(
    val enableCsp: Boolean = true,
    val frameAncestors: List<String> = listOf("'self'"),
    val enableHsts: Boolean = true,
    val xContentTypeOptions: Boolean = true
)

class SecurityHeadersMiddleware(private val tenantRegistry: TenantRegistry) {

    fun applyHeaders(call: ApplicationCall, tenantId: String) {
        val config = tenantRegistry.getTenant(tenantId)
        val policy = config?.securityPolicy ?: SecurityPolicy()

        if (policy.enableHsts) {
            call.response.headers.append("Strict-Transport-Security", "max-age=31536000; includeSubDomains")
        }
        if (policy.xContentTypeOptions) {
            call.response.headers.append("X-Content-Type-Options", "nosniff")
        }

        applyFrameProtection(call, policy, config)
    }

    private fun applyFrameProtection(call: ApplicationCall, policy: SecurityPolicy, config: TenantConfig?) {
        val frameDirective = buildFrameDirective(policy, config)
        val cspHeader = buildCspHeader(policy, frameDirective)

        call.response.headers.append("Content-Security-Policy", cspHeader)
        call.response.headers.append("X-Frame-Options", deriveXFrameOptions(frameDirective))
    }

    private fun buildFrameDirective(policy: SecurityPolicy, config: TenantConfig?): String {
        val ancestors = policy.frameAncestors.toMutableList()

        // Multi-tenant: allow parent tenant frames for embedded chat widgets
        config?.allowedOrigins?.forEach { origin ->
            if (origin.isNotBlank() && origin != "*") {
                ancestors.add(origin)
            }
        }

        return ancestors.joinToString(" ")
    }

    private fun buildCspHeader(policy: SecurityPolicy, frameDirective: String): String {
        val directives = mutableListOf<String>()
        directives.add("default-src 'self'")
        directives.add("script-src 'self' 'unsafe-inline'")
        directives.add("style-src 'self' 'unsafe-inline'")
        directives.add("connect-src 'self' wss:")

        if (policy.enableCsp) {
            directives.add("frame-ancestors ${frameDirective}")
        }

        return directives.joinToString("; ")
    }

    private fun deriveXFrameOptions(frameDirective: String): String {
        val parts = frameDirective.split(" ").filter { it.isNotBlank() }
        return when {
            parts.size == 1 && parts[0] == "'self'" -> "SAMEORIGIN"
            parts.size == 1 && parts[0] == "'none'" -> "DENY"
            else -> "ALLOW-FROM ${parts.firstOrNull { it != "'self'" } ?: ""}"
        }
    }
}

class TenantRegistry {
    private val tenants = ConcurrentHashMap<String, TenantConfig>()

    fun registerTenant(config: TenantConfig) {
        tenants[config.tenantId] = config
    }

    fun getTenant(tenantId: String): TenantConfig? = tenants[tenantId]

    fun resolveTenantFromHost(host: String): String? {
        return tenants.values.firstOrNull { config ->
            config.allowedOrigins.any { origin ->
                origin.contains(host.substringBefore(":"))
            }
        }?.tenantId ?: tenants.keys.firstOrNull()
    }
}

class ChatRoom(val roomId: String, val tenantId: String) {
    private val sessions = Collections.synchronizedSet(mutableSetOf<WebSocketSession>())

    suspend fun join(session: WebSocketSession) { sessions.add(session) }
    suspend fun leave(session: WebSocketSession) { sessions.remove(session) }
    suspend fun broadcast(message: String, sender: WebSocketSession) {
        sessions.filter { it != sender }.forEach { session ->
            try { session.send(Frame.Text(message)) } catch (_: Exception) {}
        }
    }
}

fun Application.module() {
    val tenantRegistry = TenantRegistry()
    val securityMiddleware = SecurityHeadersMiddleware(tenantRegistry)
    val chatRooms = ConcurrentHashMap<String, ChatRoom>()

    // Register default tenant with widget embedding support
    tenantRegistry.registerTenant(TenantConfig(
        tenantId = "default",
        displayName = "Default Workspace",
        allowedOrigins = listOf("https://widgets.example.com"),
        securityPolicy = SecurityPolicy(
            enableCsp = true,
            frameAncestors = listOf("'self'"),
            enableHsts = true
        )
    ))

    install(WebSockets)
    install(ContentNegotiation) { json() }

    routing {
        get("/chat/{tenantId}/{roomId}") {
            val tenantId = call.parameters["tenantId"] ?: "default"
            val roomId = call.parameters["roomId"] ?: "general"

            securityMiddleware.applyHeaders(call, tenantId)

            call.respondHtml {
                head { title { +"Chat - $roomId" } }
                body {
                    div { id = "chat-container" }
                    script { unsafe { +"initChat('$tenantId', '$roomId');" } }
                }
            }
        }

        get("/embed/{tenantId}") {
            val tenantId = call.parameters["tenantId"] ?: "default"
            val requestOrigin = call.request.headers["Origin"] ?: call.request.headers["Referer"] ?: ""

            applyEmbedSecurityHeaders(call, tenantId, requestOrigin, tenantRegistry)

            call.respondHtml {
                head { title { +"Embedded Chat Widget" } }
                body {
                    div { id = "widget-root" }
                }
            }
        }

        webSocket("/ws/{tenantId}/{roomId}") {
            val tenantId = call.parameters["tenantId"] ?: "default"
            val roomId = call.parameters["roomId"] ?: "general"
            val roomKey = "$tenantId:$roomId"

            val room = chatRooms.getOrPut(roomKey) { ChatRoom(roomId, tenantId) }
            room.join(this)

            try {
                for (frame in incoming) {
                    if (frame is Frame.Text) {
                        room.broadcast(frame.readText(), this)
                    }
                }
            } finally {
                room.leave(this)
            }
        }
    }
}

private fun applyEmbedSecurityHeaders(
    call: ApplicationCall,
    tenantId: String,
    requestOrigin: String,
    registry: TenantRegistry
) {
    val config = registry.getTenant(tenantId)
    val allowedOrigins = config?.allowedOrigins ?: emptyList()

    // Validate the requesting origin against tenant's allowed origins
    val originAllowed = allowedOrigins.any { allowed ->
        requestOrigin.contains(allowed.removePrefix("https://").removePrefix("http://"))
    }

    val frameAncestorValue = if (originAllowed && requestOrigin.isNotBlank()) {
        "'self' $requestOrigin"
    } else {
        "'self'"
    }

    // Build CSP - note: frame-ancestors is only added when enableCsp is true
    val config_policy = config?.securityPolicy
    val cspParts = mutableListOf("default-src 'self'")
    cspParts.add("script-src 'self'")

    if (config_policy?.enableCsp != false) {
        cspParts.add("frame-ancestors $frameAncestorValue")
    }

    call.response.headers.append("Content-Security-Policy", cspParts.joinToString("; "))

    // X-Frame-Options for legacy browser support
    if (!originAllowed) {
        call.response.headers.append("X-Frame-Options", "SAMEORIGIN")
    }
}

fun main() {
    embeddedServer(Netty, port = 8080) { module() }.start(wait = true)
}
